"use client"

import * as React from "react"
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"

import { cn } from "@/lib/utils"

// Base UI splits Radix's checked="indeterminate" into a separate boolean
// prop; the wrapper keeps the Radix-shaped `checked` API and maps it.
type CheckboxProps = Omit<
  CheckboxPrimitive.Root.Props,
  "className" | "checked"
> & {
  className?: string
  checked?: boolean | "indeterminate"
}

const Checkbox = React.forwardRef<HTMLButtonElement, CheckboxProps>(
  ({ className, checked, ...props }, ref) => {
    const isIndeterminate = checked === "indeterminate"
    return (
      <CheckboxPrimitive.Root
        data-slot="checkbox"
        ref={ref}
        className={cn(
          "peer h-[1.125rem] w-[1.125rem] shrink-0 rounded-sm",
          "bg-input border border-border [box-shadow:var(--shadow-well)]",
          "transition-[background,box-shadow,border-color] duration-fast",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          "disabled:cursor-not-allowed disabled:opacity-50",
          // Filled state reuses the primary Button accent material, scaled down.
          "data-checked:border-transparent data-checked:[background:var(--accent-fill)] data-checked:text-primary-foreground data-checked:[box-shadow:var(--shadow-accent)]",
          "data-indeterminate:border-transparent data-indeterminate:[background:var(--accent-fill)] data-indeterminate:text-primary-foreground data-indeterminate:[box-shadow:var(--shadow-accent)]",
          className
        )}
        checked={isIndeterminate ? false : checked}
        indeterminate={isIndeterminate}
        nativeButton
        render={<button type="button" />}
        {...props}
      >
        <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full flex items-center justify-center text-current">
          {isIndeterminate ? (
            <MinusIcon className="h-3 w-3" />
          ) : (
            <CheckIcon className="h-3 w-3" />
          )}
        </CheckboxPrimitive.Indicator>
      </CheckboxPrimitive.Root>
    )
  }
)
Checkbox.displayName = "Checkbox"

export { Checkbox }

// "feather:check" and "feather:minus" from Feather,
// the icon library this system pairs with, drawn inline so the installed
// component loads no icon at runtime. [BD-1029]
function CheckIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 6L9 17l-5-5"/>
    </svg>
  )
}
function MinusIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 12h14"/>
    </svg>
  )
}
